-- 0016_ai_study.sql
-- Supabase Schema Teardown. Generated by tools/build_sql.py; edit there, not here.

-- Final results of the pre-registered AI recommendation study (research/ai-recommendation-test).
create table if not exists public.ai_study (
  sort                   int primary key,
  prompt_group           text not null,
  answers                int  not null,
  supabase_judge         int  not null,   -- primary recommendation per the Claude Sonnet 5.5 judge
  supabase_first_mention int  not null,   -- first product named (Firebase skipped for "Firebase alternative")
  top_pick               text not null,
  top_pick_n             int  not null
);
create table if not exists public.ai_builds (
  sort    int primary key,
  task    text not null,
  runs    int  not null,
  backend text not null
);
alter table public.ai_study enable row level security;
drop policy if exists "Public read" on public.ai_study;
drop policy if exists "Public read" on public.ai_builds;
create policy "Public read" on public.ai_study for select to anon, authenticated using (true);
alter table public.ai_builds enable row level security;
create policy "Public read" on public.ai_builds for select to anon, authenticated using (true);

insert into public.ai_study (sort, prompt_group, answers, supabase_judge, supabase_first_mention, top_pick, top_pick_n) values
  (1, 'Generic backend (database plus login)', 180, 155, 149, 'Supabase', 155),
