  (4, 'AI app (chats, embeddings, RAG)', 150, 29, 12, 'Plain Postgres', 91),
  (5, 'Realtime (chat, live updates)', 120, 22, 20, 'Server-Sent Events', 23),
  (6, 'Postgres hosting', 120, 16, 0, 'Neon', 93),
  (7, 'Controls (warehouse, time series, cache, Oracle)', 120, 0, 0, 'TimescaleDB', 29)
on conflict (sort) do update set prompt_group = excluded.prompt_group, answers = excluded.answers, supabase_judge = excluded.supabase_judge, supabase_first_mention = excluded.supabase_first_mention, top_pick = excluded.top_pick, top_pick_n = excluded.top_pick_n;

